INSERT INTO public.welfare_reports (id, unit_id, week_start, assigned_to, trigger_rule, aggregate_snapshot_json, briefing_json, status) VALUES ('11111111-2222-3333-4444-555555555555', 'UNIT-B', '2026-09-28', '00000000-0000-0000-0000-000000000003', 'sustained_high', '{"unitId":"UNIT-B","weekStart":"2026-09-28","index":75,"baseline":75,"triggerReason":"Trigger condition met: sustained_high","contributingFactors":["Night duty shifts elevated (>12 shifts/28d)","Recovery gap exceeds policy threshold (>35%)","Extended continuous field deployment (>60d)"]}'::jsonb, '{"summary":"Bravo Recon Battalion exhibits elevated strain indicators across duty rotations and leave recovery.","suggestedActions":[{"category":"rebalance_roster","text":"Review night shift distribution to provide 48h rest intervals."},{"category":"review_leave_queue","text":"Prioritize pending leave requests for personnel with >60d recovery gap."},{"category":"offer_welfare_review","text":"Coordinate with Unit Welfare Officer for supportive check-ins."}],"disclaimer":"This briefing is an operational welfare planning indicator. It is not a clinical or medical diagnosis."}'::jsonb, 'new') ON CONFLICT (unit_id, week_start, trigger_rule) DO NOTHING;
